(* [comment removed for export] *)
Lemma amb_exit : forall (rax s0x s1x s2x gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (rav s0v s1v s2v : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) (SP lo : Z),
  rw_cells bsegs m (SP + -32) (mb_frame s2v s1v s0v rav) ->
  stk bsegs m lo (SP + -32) -> 0 <= lo -> lo + 32 <= SP -> SP <= 2^64 -> mem_inv bsegs m ->
  evt bsegs (fun ms' => ms' = MS (mkR rav (wz SP) gp tp t0 t1 t2 s0v s1v a0 a1 a2 a3 a4 a5 a6 a7 s2v s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                            F (ret_pc rav) fc None m (seg_rom bsegs)
                      /\ stk bsegs m lo SP)
    (MS (mkR rax (wz (SP + -32)) gp tp t0 t1 t2 s0x s1x a0 a1 a2 a3 a4 a5 a6 a7 s2x s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
