(* [comment removed for export] *)
Definition amb_rem (m : mem) (LBc : list block) (hL : Z) (bs : list block) (es : list mbe) : Prop :=
  forall A b B, bs = A ++ b :: B ->
    In b LBc /\ exists sz (wprev : word) junk, In (blk_addr b, sz) es /\ blk_size b = mb_block_size sz
      /\ rw_cells bsegs m (blk_addr b) [C8 (wz (lhead hL (map blk_addr B))); C8 wprev]
      /\ rw_cells bsegs m (blk_addr b + 16) [C8 (wz sz); CB (Z.to_nat (mb_block_size sz - 24)) junk]
      /\ addressable m (blk_addr b) (mb_block_size sz).

(* [comment removed for export] *)
Lemma mbe_blob : forall m x nxt (wprev : word) sz junk,
  0 <= sz ->
  rw_cells bsegs m x [C8 (wz nxt); C8 wprev] -> rw_cells bsegs m (x + 16) [C8 (wz sz); CB (Z.to_nat (mb_block_size sz - 24)) junk] ->
  exists bs, rw_cells bsegs m x [CB (Z.to_nat (mb_block_size sz)) bs].
Proof.
  intros m x nxt wprev sz junk S0 LN PL. pose proof (mb_block_size_range sz S0) as [[R1 R2] R8].
  assert (C : rw_cells bsegs m x ([C8 (wz nxt); C8 wprev] ++ [C8 (wz sz); CB (Z.to_nat (mb_block_size sz - 24)) junk])).
  { apply rw_cells_app. split; [exact LN|]. cbn [cells_size csize Nat.add]. replace (x + Z.of_nat 16) with (x + 16) by lia. exact PL. }
  destruct (rw_cells_forget _ _ _ _ C) as [bb K]. exists bb.
  cbn [cells_size csize Nat.add app] in K.
  replace (Z.to_nat (mb_block_size sz)) with (8 + (8 + (8 + (Z.to_nat (mb_block_size sz - 24) + 0))))%nat by lia. exact K.
Qed.

Section W.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.
  Hypothesis ATR : incl TRLIST (as_TR H).

  (* [comment removed for export] *)
  Definition ambI_post (sp gp s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : as_St H) (LBc : list block) (LF : list fframe) (hL lo B shi : Z) (b : block) (R : list block) (es : list mbe) (errv : word)
      (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (s' : as_St H),
      let nxt := lhead hL (map blk_addr R) in
      let LB1 := as_lb_remove H (blk_id b) LBc in
      as_VIS H s' (cfg_ms c) = MS (mkR (wz AMB_RA) (wz (bv_unsigned sp + -32)) gp (wz ATP) t0 t1 t2 (wz hL) (wz ASHADOW_BASE) (wz nxt) a1 a2 a3 a4 a5 a6 a7
                                       (wz nxt) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                                  F (wz (if nxt =? hL then AMB_EXIT else AMB_LOOP)) fc None m' (seg_rom bsegs)
      /\ as_AKREL H s' c /\ as_MPRES H mo (cfg_model c)
      /\ mem_inv bsegs m' /\ stk bsegs m' lo (bv_unsigned sp + -32)
      /\ rw_cells bsegs m' AERRNO [C4 errv] /\ as_rauxv_ok H m' B
      /\ as_RHEAP H s' LB1 m'
      /\ apres H LB1 (bv_unsigned sp + -32) m m'
